 }

classDiagram
class User{
  +id: UUID
  +email: str
  +password_hash: str
  +cart: Cart
  +orders: List[Order]
}
class Cart{
  +id: UUID
  +items: List[CartItem]
  +user: User
}
class CartItem{
  +id: UUID
  +product: Product
  +quantity: int
}
class Product{
  +id: UUID
  +name: str
  +price: float
  +stock: int
}
class Order{
  +id: UUID
  +user: User
  +items: List[OrderItem]
  +total: float
  +payment_status: str
}
class OrderItem{
  +id: UUID
  +product: Product
  +quantity: int
  +price: float
}
User "0..1" --"owns" Cart
User "0..1" --"has" Order
Product "0..1" --"included in" OrderItem
